/**
 * Siembra las plantillas de consentimiento de una clinica (idempotente por
 * `[tenantId, clave]`): crea las que faltan y NO pisa las editadas. Se llama en
 * el alta de la clinica y en el seed para las que ya existen.
 */
/** Acceso mínimo a Prisma: vale el cliente global y la transacción del alta. */
export interface DbPlantillasConsentimiento {
  consentimientoPlantilla: {
    findUnique: (a: unknown) => Promise<{ id: string } | null>;
    create: (a: unknown) => Promise<unknown>;
  };
}

export async function sembrarPlantillasConsentimiento(
  prisma: DbPlantillasConsentimiento,
  tenantId: string,
): Promise<number> {
  let creadas = 0;
  for (const plantilla of PLANTILLAS_CONSENTIMIENTO) {
    const existente = await prisma.consentimientoPlantilla.findUnique({
      where: { tenantId_clave: { tenantId, clave: plantilla.clave } },
    });
    if (existente) continue;
    await prisma.consentimientoPlantilla.create({
      data: {
        tenantId,
        clave: plantilla.clave,
        titulo: plantilla.titulo,
        cuerpo: plantilla.cuerpo,
        activo: plantilla.activo ?? true,
      },
    });
    creadas++;
  }
  return creadas;
}